#[test]fn item_http_requires_flushed_matching_original_and_correlated_delivery(){
 use crate::{g3_journal::{Journal,Phase,operation_digest},g3_local_consumer::LocalConsumer};
 let dir=std::env::temp_dir().join(format!("nt2-item-http-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&dir).unwrap();let path=dir.join("originals.jsonl");
 let mut owner=owner();let mut consumer=LocalConsumer::new(Journal::open(&path).unwrap());consumer.bind(owner.binding.clone()).unwrap();
 let id=uuid::Uuid::new_v4().to_string();let payload=serde_json::json!({"catalogueRevision":"nt2-items-base-2","spell":{"actionId":"LIGHT_BULLET","usesRemaining":"0"}});
 let bytes=consumer.begin_item_with_id(crate::g3_items::Original{kind:"deposit".into(),payload_json:payload.to_string()},consumer.generation(),id.clone()).unwrap();let request:wire::Request=serde_json::from_slice(&bytes).unwrap();let value:serde_json::Value=serde_json::from_slice(&bytes).unwrap();let sent=Arc::new(AtomicU64::new(0));
 for field in ["operationId","item"]{let mut bad=value.clone();bad["itemDeposit"][field]=if field=="operationId"{serde_json::json!(uuid::Uuid::new_v4().to_string())}else{serde_json::json!({"catalogueRevision":"nt2-items-base-2","spell":{"actionId":"BOMB","usesRemaining":"9"}})};let spy=sent.clone();assert!(tauri::async_runtime::block_on(owner.submit_item_via(&mut consumer,serde_json::to_vec(&bad).unwrap(),move|_,_|{spy.fetch_add(1,Ordering::AcqRel);Box::pin(async{Err("must not send".into())})})).is_err());}
 assert_eq!(sent.load(Ordering::Acquire),0);assert_eq!(owner.count,0);assert!(tauri::async_runtime::block_on(owner.call(bytes.clone())).is_err());
 let original=consumer.journal.pending().next().unwrap().record.original;let operation=wire::ItemOperation{operation_id:Some(id.clone()),principal_id:Some(original.principal_id.clone()),original_scope:request.scope.clone(),direction:Some("deposit".into()),item_id:Some(uuid::Uuid::new_v4().to_string()),delivery_id:Some(uuid::Uuid::new_v4().to_string()),payload_digest:Some(operation_digest(&original).unwrap()),item:request.item_deposit.as_ref().unwrap().item.clone(),state:Some("awaiting_local".into()),effect_allowed:Some(true),save_persistence:Some("unproven".into()),..Default::default()};
 let mut response:wire::Response=serde_json::from_slice(&reply(&request)).unwrap();response.ghosts=None;response.item_operation=Some(operation.clone());let good=serde_json::to_vec(&response).unwrap();
 let mut bad=response.clone();bad.item_operation.as_mut().unwrap().payload_digest=Some("a".repeat(64));let bad=serde_json::to_vec(&bad).unwrap();assert!(tauri::async_runtime::block_on(owner.submit_item_via(&mut consumer,bytes.clone(),move|_,_|Box::pin(async move{Ok(bad)}))).is_err());assert_eq!(consumer.journal.pending().next().unwrap().record.phase,Phase::Requested);
 // Use a fresh owner to avoid the intentional per-owner minimum call spacing.
 let mut next=super::tests::owner();let out=tauri::async_runtime::block_on(next.submit_item_via(&mut consumer,bytes,move|_,_|Box::pin(async move{Ok(good)}))).unwrap();assert_eq!(out.item_operation.unwrap().operation_id.as_deref(),Some(id.as_str()));assert_eq!(consumer.journal.pending().next().unwrap().record.phase,Phase::ServerAccepted);let p=consumer.journal.prepare_effect(&id).unwrap();consumer.journal.finish_session_effect(p,true).unwrap();assert!(consumer.journal.prepare_effect(&id).is_err());drop(consumer);let mut cold=Journal::open(&path).unwrap();assert!(cold.recover_item_unissued(&operation).is_err());drop(cold);std::fs::remove_file(path).unwrap();std::fs::remove_dir(dir).unwrap();
}
#[test]fn item_inventory_publish_empty_ack_and_inspect_view_are_distinct(){
 for publish in [true,false]{for view_present in [true,false]{let mut o=owner();let mut q=request(&o);q.ghost_list=None;
  if publish{q.inventory_publish=Some(wire::InventoryPublish{revision:Some(1),wands:Some(vec![]),held_slot:Some("-1".into())});}
  else{q.inventory_inspect=Some(wire::InventoryInspect{game_session_id:Some(uuid::Uuid::new_v4().to_string()),slot:Some(0)});}
  let now=Instant::now();let ticket=o.plan(&serde_json::to_vec(&q).unwrap(),now).unwrap();let mut r:wire::Response=serde_json::from_slice(&reply(&q)).unwrap();r.ghosts=None;r.inventory=view_present.then(wire::InventoryView::default);
  assert_eq!(o.complete(ticket,Ok(serde_json::to_vec(&r).unwrap()),now).is_ok(),publish!=view_present,"Only inspect returns InventoryView; publish acknowledges with the correlated envelope");
 }}
 // Neither an ACK nor a view can smuggle a second response category.
 let mut o=owner();let mut q=request(&o);q.ghost_list=None;q.inventory_publish=Some(wire::InventoryPublish::default());let now=Instant::now();let ticket=o.plan(&serde_json::to_vec(&q).unwrap(),now).unwrap();let mut r:wire::Response=serde_json::from_slice(&reply(&q)).unwrap();r.ghosts=None;r.item_bank=Some(wire::ItemBankSnapshot::default());assert!(o.complete(ticket,Ok(serde_json::to_vec(&r).unwrap()),now).is_err());
}
#[test]fn item_receipt_original_scope_request_accepts_only_matching_operation_response(){
 let mut o=owner();let mut q=request(&o);q.ghost_list=None;q.current_scope=q.scope.clone();let id=uuid::Uuid::new_v4().to_string();let delivery=uuid::Uuid::new_v4().to_string();
 q.item_receipt=Some(wire::ItemReceipt{operation_id:Some(id.clone()),delivery_id:Some(delivery.clone()),payload_digest:Some("a".repeat(64)),receipt_id:Some(id.clone()),outcome:Some("escrowed".into()),evidence_digest:Some("b".repeat(64))});
 let now=Instant::now();let ticket=o.plan(&serde_json::to_vec(&q).unwrap(),now).unwrap();let mut r:wire::Response=serde_json::from_slice(&reply(&q)).unwrap();r.ghosts=None;r.item_operation=Some(wire::ItemOperation{operation_id:Some(id),delivery_id:Some(delivery),original_scope:q.scope.clone(),principal_id:Some(o.binding.principal_id.clone()),direction:Some("deposit".into()),state:Some("completed".into()),save_persistence:Some("unproven".into()),..Default::default()});assert!(o.complete(ticket,Ok(serde_json::to_vec(&r).unwrap()),now).is_ok());
 let mut o=owner();let ticket=o.plan(&serde_json::to_vec(&q).unwrap(),now).unwrap();r.item_operation.as_mut().unwrap().original_scope.as_mut().unwrap().world_token=Some("foreign".into());assert!(o.complete(ticket,Ok(serde_json::to_vec(&r).unwrap()),now).is_err());
}
